import{_ as t,o as a,c as o,ag as d}from"./chunks/framework.DaCm-iTo.js";const m=JSON.parse('{"title":"PlaceholderAPI Placeholders","description":"","frontmatter":{},"headers":[],"relativePath":"en/modules/storage/placeholders.md","filePath":"en/modules/storage/placeholders.md","lastUpdated":null}'),r={name:"en/modules/storage/placeholders.md"};function l(s,e,n,c,i,h){return a(),o("div",null,[...e[0]||(e[0]=[d('<h1 id="placeholderapi-placeholders" tabindex="-1">PlaceholderAPI Placeholders <a class="header-anchor" href="#placeholderapi-placeholders" aria-label="Permalink to &quot;PlaceholderAPI Placeholders&quot;">​</a></h1><p>EmakiStorage registers a PlaceholderAPI extension when PlaceholderAPI is present. The identifier is <code>emakistorage</code>. The placeholders work in scoreboards, menus, chat formats, boss bars, action bars and any other plugin text template that supports PlaceholderAPI.</p><p>If PlaceholderAPI is not installed, EmakiStorage itself still runs normally; it simply does not register the <code>%emakistorage_*%</code> external placeholders.</p><h2 id="placeholder-list" tabindex="-1">Placeholder List <a class="header-anchor" href="#placeholder-list" aria-label="Permalink to &quot;Placeholder List&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Placeholder</th><th>Description</th></tr></thead><tbody><tr><td><code>%emakistorage_used_slots%</code></td><td>Slots currently holding an entry.</td></tr><tr><td><code>%emakistorage_total_slots%</code></td><td>Effective total slots.</td></tr><tr><td><code>%emakistorage_free_slots%</code></td><td>Remaining free slots.</td></tr><tr><td><code>%emakistorage_purchased_slots%</code></td><td>Purchased slots.</td></tr><tr><td><code>%emakistorage_granted_slots%</code></td><td>Granted slots.</td></tr><tr><td><code>%emakistorage_pages%</code></td><td>Total pages.</td></tr><tr><td><code>%emakistorage_stack_limit%</code></td><td>The currently effective player-level per-slot ceiling.</td></tr><tr><td><code>%emakistorage_sort_mode%</code></td><td>The current sort mode id.</td></tr><tr><td><code>%emakistorage_total_amount%</code></td><td>Summed amount across every entry, saturating at <code>Long.MAX_VALUE</code>.</td></tr><tr><td><code>%emakistorage_count_&lt;token&gt;%</code></td><td>Stored amount for the given ItemSource token, <code>0</code> when absent.</td></tr></tbody></table><h2 id="resolution-thread-and-unloaded-data" tabindex="-1">Resolution Thread and Unloaded Data <a class="header-anchor" href="#resolution-thread-and-unloaded-data" aria-label="Permalink to &quot;Resolution Thread and Unloaded Data&quot;">​</a></h2><p>Every placeholder reads the in-memory storage of an online player and never loads from disk: a placeholder resolves on whatever thread PAPI calls it from, so blocking IO is not an option. An unloaded storage reports <code>0</code>, and an unrecognised placeholder returns an empty string.</p><h2 id="related-pages" tabindex="-1">Related Pages <a class="header-anchor" href="#related-pages" aria-label="Permalink to &quot;Related Pages&quot;">​</a></h2><ul><li><a href="./capacity.html">Capacity</a>: the four-source capacity model behind <code>total_slots</code>, <code>purchased_slots</code> and friends.</li><li><a href="./events.html">Event API</a>: the Bukkit events to use when you need to intercept rather than only read.</li><li><a href="./api.html">API and Integration</a>: reading capacity and stored amounts from code.</li></ul>',9)])])}const u=t(r,[["render",l]]);export{m as __pageData,u as default};
